<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class TrainingSession extends Model { protected $fillable=['company_id','training_program_item_id','training_topic_id','attendance_event_id','uuid','title','description','training_type','session_purpose','induction_scope','reinduction_cause','scheduled_start_at','scheduled_end_at','actual_start_at','actual_end_at','planned_duration_minutes','actual_duration_minutes','modality','location','virtual_link','instructor_type','instructor_employee_id','external_instructor_id','status','audience_type','audience_description','specific_employee_ids','called_snapshot','requires_attendance','requires_signature','requires_material','requires_execution_report','extraordinary_reason','extraordinary_origin','content_delivered','execution_notes','coverage_percentage','notes','created_by','updated_by']; protected $casts=['scheduled_start_at'=>'datetime','scheduled_end_at'=>'datetime','actual_start_at'=>'datetime','actual_end_at'=>'datetime','specific_employee_ids'=>'array','called_snapshot'=>'array','requires_attendance'=>'boolean','requires_signature'=>'boolean','requires_material'=>'boolean','requires_execution_report'=>'boolean','coverage_percentage'=>'decimal:2']; public function getRouteKeyName(){return'uuid';} public function company(){return $this->belongsTo(PerfilEmpresa::class,'company_id');} public function programItem(){return $this->belongsTo(TrainingProgramItem::class,'training_program_item_id');} public function topic(){return $this->belongsTo(TrainingTopic::class,'training_topic_id');} public function instructorEmployee(){return $this->belongsTo(Empleado::class,'instructor_employee_id');} public function externalInstructor(){return $this->belongsTo(TrainingInstructor::class,'external_instructor_id');} public function attendanceEvent(){return $this->belongsTo(AttendanceEvent::class);} public function attendance(){return $this->morphOne(AttendanceEvent::class,'attendable');} public function evidences(){return $this->hasMany(TrainingSessionEvidence::class);} public function reminders(){return $this->hasMany(TrainingSessionReminder::class);} public function changes(){return $this->hasMany(TrainingSessionChange::class);} public function evaluations(){return $this->hasMany(TrainingEvaluation::class);} public function scopeForCompany($q,int$id){return$q->where('company_id',$id);} }
